<?php
$pageTitle='Reportes administrativos';$basePath='../';$adminScripts=true;$adminActive='reportes';require_once __DIR__.'/../auth.php';requireAdmin('../login.php','../usuario/index.php');require_once __DIR__.'/../firebase-data.php';
$period=normalizePeriod($_GET['period']??null,['today','day','month','year','range'],'today');$tz=new DateTimeZone('America/La_Paz');$now=new DateTimeImmutable('now',$tz);$start=match($period){'day'=>(firebaseDate($_GET['from']??'')?->setTime(0,0)??$now->setTime(0,0)),'month'=>$now->modify('first day of this month')->setTime(0,0),'year'=>$now->setDate((int)$now->format('Y'),1,1)->setTime(0,0),'range'=>firebaseDate($_GET['from']??'')?->setTime(0,0)??$now->setTime(0,0),default=>$now->setTime(0,0)};$end=match($period){'day'=>$start->setTime(23,59,59),'range'=>(firebaseDate($_GET['to']??'')?->setTime(23,59,59)??$now->setTime(23,59,59)),default=>$now};
$all=array_values(array_filter(firebaseRead(fn(FirebaseReadService $f)=>$f->collection('pedidos')), 'is_array'));$orders=array_values(array_filter($all,fn($o)=>inAdminPeriod($o['fechaCreacion']??null,$start,$end,$tz)));$sales=array_values(array_filter($orders,'isValidSale'));$total=array_sum(array_map(fn($o)=>(float)($o['total']??0),$sales));$products=[];$presentations=[];$payments=[];$origins=[];
foreach($sales as $o){$payments[(string)($o['metodoPago']??'No especificado')]=($payments[(string)($o['metodoPago']??'No especificado')]??0)+1;$origin=orderOrigin($o);$origins[$origin]=($origins[$origin]??0)+1;foreach(orderItems($o) as $item)if(is_array($item)){$name=(string)($item['nombre']??'Sin detalle');$q=(int)($item['cantidad']??1);$products[$name]=($products[$name]??0)+$q;$size=(string)($item['cantidadMl']??'Sin datos').' ml';$presentations[$size]=($presentations[$size]??0)+$q;}}arsort($products);$top=array_key_first($products);
require __DIR__.'/../header.php';require __DIR__.'/../navbar.php';require __DIR__.'/../admin-nav.php';
