<main id="contenido" class="admin-page reports-page"><section class="admin-head admin-head--with-nav"><div class="container"><div><span class="eyebrow eyebrow--light">Análisis comercial</span><h1>Reportes CHICHEJ</h1><p>Vista previa exacta de los datos que alimentarán el PDF futuro.</p></div><span class="status-pill status-pill--active">● Solo lectura</span></div></section><section class="section section--cream"><div class="container"><form class="report-toolbar" method="get"><div class="report-periods"><?php foreach(['today'=>'Hoy','day'=>'Día','month'=>'Mes','year'=>'Año','range'=>'Rango'] as $key=>$label):?><button name="period" value="<?=$key?>" class="<?=$period===$key?'is-active':''?>"><?=$label?></button><?php endforeach;?></div><div class="report-range"><label>Desde<input type="date" name="from" value="<?=h($start->format('Y-m-d'))?>"></label><label>Hasta<input type="date" name="to" value="<?=h($end->format('Y-m-d'))?>"></label><button class="button button--ghost">Vista previa</button><button class="button button--primary" type="button" disabled>Generar PDF</button></div></form><div class="report-context"><span class="status-pill status-pill--active">● <?=h($start->format('d/m/Y'))?>–<?=h($end->format('d/m/Y'))?></span><p>Pago aprobado, no cancelado y método distinto de admin.</p></div><div class="report-metrics"><article><small>Total vendido</small><strong><?=h(money($total))?></strong><span><?=count($sales)?> ventas válidas</span></article><article><small>Pedidos</small><strong><?=count($orders)?></strong><span>En el período</span></article><article><small>Producto líder</small><strong><?=h($top??'Sin datos')?></strong><span><?=$top?$products[$top].' unidades':'Sin ventas'?></span></article><article><small>Ticket promedio</small><strong><?=h($sales?money($total/count($sales)):'Sin datos')?></strong></article></div><div class="report-grid"><section class="report-card"><h2>Presentaciones</h2><ul class="metric-bars"><?php foreach($presentations as $k=>$v):?><li><span><?=h($k)?></span><i style="--value:<?=count($sales)?min(100,round($v/max(1,max($presentations))*100)):0?>%"></i><b><?=$v?></b></li><?php endforeach;?><?php if(!$presentations):?><li>Sin datos</li><?php endif;?></ul></section><section class="report-card"><h2>Origen</h2><ul class="metric-bars"><?php foreach($origins as $k=>$v):?><li><span><?=h($k)?></span><i style="--value:<?=count($sales)?round($v/count($sales)*100):0?>%"></i><b><?=$v?></b></li><?php endforeach;?><?php if(!$origins):?><li>Sin datos</li><?php endif;?></ul></section><section class="report-card"><h2>Métodos de pago</h2><ul class="metric-bars"><?php foreach($payments as $k=>$v):?><li><span><?=h($k)?></span><i style="--value:<?=count($sales)?round($v/count($sales)*100):0?>%"></i><b><?=$v?></b></li><?php endforeach;?><?php if(!$payments):?><li>Sin datos</li><?php endif;?></ul></section><section class="report-card report-card--orders admin-data" data-filter-scope><div class="analytics-head"><h2>Pedidos incluidos</h2><span data-filter-count><?=count($orders)?> registros</span></div><label class="admin-search">Buscar<input type="search" data-filter-search placeholder="ID, usuario, producto u origen…"></label><div class="report-orders-scroll"><?php foreach($orders as $o):?><article data-filter-row data-search="<?=h(implode(' ',[$o['pedidoId']??$o['_id'],$o['nombreUsuario']??'',orderSummary($o),orderOrigin($o)]))?>"><b><?=h($o['pedidoId']??$o['_id'])?></b><span><?=h($o['nombreUsuario']??'Sin usuario')?></span><span><?=h(orderSummary($o))?></span><span><?=h(orderOrigin($o))?></span><strong><?=h(money($o['total']??null))?></strong></article><?php endforeach;?></div><p data-filter-empty hidden>Sin coincidencias.</p></section></div></div></section></main>
